import sys

def main():
    input = sys.stdin.read().split()
    index = 0
    while True:
        n = int(input[index])
        if n == 0:
            break
        index += 1
        permutation = list(map(int, input[index:index+n]))
        index += n
        inverse_permutation = [0] * n
        for i, value in enumerate(permutation):
            inverse_permutation[value-1] = i + 1
        if permutation == inverse_permutation:
            print("ambiguous")
        else:
            print("not ambiguous")

main()
